claims.statement_tex:
For every adjoint-valued form $\alpha$,
\begin{equation}
 d_A^2\alpha=[F_A\wedge\alpha],\qquad d_AF_A=0.
 \label{eq:curvature-square}
\end{equation}
Consequently, if $F_A=0$, the sequence
$\Omega^0(\operatorname{ad}P)\xrightarrow{d_A}
\Omega^1(\operatorname{ad}P)\xrightarrow{d_A}\cdots$ is a complex.

For $a,b\in\Omega^1(M;\operatorname{ad}P)$,
\begin{align}
 F_{A+ta}&=F_A+t\,d_Aa+\tfrac12t^2[a\wedge a],\label{eq:curvature-variation}\\
 DS_A(a)&=g^{-2}\langle d_A^*F_A,a\rangle_{L^2},\label{eq:ym-first}\\
 D^2S_A(a,b)&=g^{-2}\left(
 \langle d_Aa,d_Ab\rangle_{L^2}
 +\langle F_A,[a\wedge b]\rangle_{L^2}\right).
 \label{eq:ym-second}
\end{align}
Thus a smooth connection is stationary for all permitted variations if and
only if $d_A^*F_A=0$.

For an $SU(2)$ bundle on a closed, connected, oriented Riemannian four-manifold,
write $k=\langle c_2(P\times_{SU(2)}\mathbb C^2),[M]\rangle$ with
the convention in which anti-self-dual instantons have positive $k$.
Then
\begin{equation}
 \operatorname{ind}L_A=8k-3(1-b_1(M)+b_2^+(M)).
 \label{eq:asd-index}
\end{equation}

\label{prop:micro-slater}
If $e_1,\ldots,e_M$ are an orthonormal basis of the finite-dimensional
one-particle space $V$, then for
$1\le i_1<\cdots<i_N\le M$ the tensors
\[
 \Psi_{i_1\cdots i_N}
 =\frac1{\sqrt{N!}}\sum_{\sigma\in S_N}
   \operatorname{sgn}(\sigma)
   e_{i_{\sigma(1)}}\otimes\cdots\otimes e_{i_{\sigma(N)}}
\]
form an orthonormal basis of $\bigwedge^N V$.  In particular,
$\dim\bigwedge^N\C^M=\binom MN$, with the dimension zero for
$N>M$.

\label{prop:micro-bornhuang}
Set
\[
 \begin{aligned}
 d_{mn}&=\langle\phi_m,\nabla_R\phi_n\rangle,\\
 \tau_{mn}&=\langle\phi_m,\Delta_R\phi_n\rangle.
 \end{aligned}
\]
Then $H\Psi=E\Psi$ is equivalent to
\begin{equation}
 -\frac{\hbar^2}{2M}
  \left(\Delta\chi_m+
        2\sum_n d_{mn}\cdot\nabla\chi_n+
        \sum_n\tau_{mn}\chi_n\right)
  +E_m(R)\chi_m=E\chi_m
 \label{eq:micro-bornhuang}
\end{equation}
for each $m$.  Moreover, $d_{mn}=-\overline{d_{nm}}$ componentwise.

\label{thm:micro-H}
Let $f(t,v)>0$ be a differentiable solution of
$\partial_tf=Q(f,f)$ for which $\int f\log f$ is finite,
differentiation under the integral is valid, and all terms in
\eqref{eq:micro-weak-Q} with $\phi=\log f$ are integrable.
Then
\begin{equation}
 \frac{d}{dt}\int f\log f\,dv=-D(f)\le0,
 \quad
 D(f)=\frac14\iiint B(f'f_*'-ff_*)
           \log\frac{f'f_*'}{ff_*}\,dn\,dv_*\,dv.
 \label{eq:micro-H}
\end{equation}

\label{prop:micro-entropy-counterexample}
There is a probability density supported in $[0,1]^3$ with finite
second moment and $\int f\log f=+\infty$.

\label{prop:micro-moments}
Under these hypotheses,
\begin{align}
 \partial_t\rho+\nabla\cdot(\rho u)&=0,
 \label{eq:micro-mass}\\
 \partial_t(\rho u)+\nabla\cdot(\rho u\otimes u+P)&=0,
 \label{eq:micro-momentum}\\
 \partial_tE+\nabla\cdot(Eu+Pu+q)&=0.
 \label{eq:micro-energy}
\end{align}

\label{prop:micro-learned-entropy}
For $T>0$, let the viscous stress be
$\tau=2\mu S_0+\zeta(\nabla\cdot u)I$ and the heat flux
$q=-\kappa\nabla T$, with $\mu,\zeta,\kappa\ge0$.
Then
\[
 \frac{\tau:\nabla u}{T}
       -\frac{q\cdot\nabla T}{T^2}
 =\frac{2\mu|S_0|^2}{T}
  +\frac{\zeta(\nabla\cdot u)^2}{T}
  +\frac{\kappa|\nabla T|^2}{T^2}\ge0.
\]

\label{prop:ns-similarity-chain-rule}
For $\tau>0$ and $z\in\R$ there is a unique
$q>|z|^{1/D}$ with $q-z^2q^{2h}=\tau$. Set $\eta=zq^{-D}$,
$d=1-\eta^2$, and $L=1-2h\eta^2$. Then $|\eta|<1$, $L\geq1-2h>0$,
and for a smooth profile $G(X,\eta)$ and any real $b$,
\begin{align*}
 \partial_t(q^bG)&=q^{b-1}L^{-1}
     (-bG+D\eta\partial_\eta G+X\partial_XG),\\
 \partial_z(q^bG)&=q^{b-D}L^{-1}
     (2b\eta G+d\partial_\eta G-2\eta X\partial_XG).
\end{align*}

